// CSD_RATIONALE_BEGIN
// Diagnosis from attempt 43 (best: 52%, 99% syntax) and attempt 55 (44.3%, 82%):
//
// The dominant failure mode (167/300 wrong) is "syntax-valid but semantically wrong SQL":
//   - Hallucinated table/column names not present in the schema
//   - Missing JOIN chains (single table instead of multi-table join)
//   - Missing WHERE / GROUP BY / HAVING / ORDER BY clauses
//
// The FROM guard in attempt 55 regressed (to 44.3%) because it used
// CSDHelpers.CountTokenOccurrences (not in the approved set) and
// helpers.SafeBoostedConstrainedStep (also not in the approved set),
// causing non-standard code paths.
//
// New approach: replace the GroupBoostedConstrainedStep inner loop with
// RegenerateUnitOnGroundingFailure, which was designed precisely for this
// failure mode in schema-guided SQL tasks. It generates token by token under
// hard parser control, detects when a schema symbol (table/column) completes,
// checks if that identifier appears in the prompt (schema + question), and
// rolls back + resamples grounded identifiers. This directly addresses the
// 141 semantic-mismatch examples.
//
// Phase layout (maxSteps=900):
//   Phase 1 – Short unconstrained preamble (≤5 steps) for "SQL: " prefix.
//   Phase 2 – Force-open "<<" if preamble did not naturally open a span.
//   Phase 3 – RegenerateUnitOnGroundingFailure with budget = (remaining - 2),
//              reserving 2 steps for closing. Updates generated + currentConstrainedOut.
//   Phase 4 – CloseSpanWithinBudget(2) emits ">>" and validates closure.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 (preamble loop):
//   The loop guard includes !insideConstrainedOut, so insideConstrainedOut can
//   only flip to true inside the loop body when RenderedEndsWith fires, at which
//   point we set currentConstrainedOut := []. IsValidPrefix([]) holds by the
//   method precondition. EOS leaves insideConstrainedOut false, making the
//   implication vacuously true.
//
// Phase 2 (OpenConstrainedSpan):
//   Only reached when !insideConstrainedOut. The helper sets
//   currentConstrainedOut := []; IsValidPrefix([]) holds by precondition.
//
// Phase 3 (RegenerateUnitOnGroundingFailure):
//   The helper's postcondition guarantees parser.IsValidPrefix(resultConstrained).
//   We assign currentConstrainedOut := resultConstrained, preserving the invariant.
//
// Phase 4 (CloseSpanWithinBudget):
//   The helper's postcondition guarantees insideOut ==> parser.IsValidPrefix(currentOut).
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: Each iteration increments steps by 1 and appends at most 1 token
//   (0 on EOS, 1 on non-EOS). Ratio ≤ 1:1 each iteration.
//
// Phase 2: OpenConstrainedSpan increments steps by 1 and appends exactly 1 "<<"
//   token. Net growth 1:1, bound preserved.
//
// Phase 3: After RegenerateUnitOnGroundingFailure with budget sqlBudget:
//   generated = stablePrefix + resultConstrained.
//   |stablePrefix| = |generated_before| - |currentConstrainedOut_before|.
//   Helper postcondition: |resultConstrained| <= |currentConstrainedOut_before| + sqlBudget.
//   Therefore |generated_after| <= |generated_before| - |currentConstrainedOut_before|
//     + |currentConstrainedOut_before| + sqlBudget = |generated_before| + sqlBudget.
//   steps_after = steps_before + sqlBudget.
//   By induction: |generated_after| <= |generatedPrefix| + steps_after. ✓
//
// Phase 4: CloseSpanWithinBudget postcondition:
//   |generatedOut| <= |generated_before_phase4| + closingBudget.
//   steps_after = steps_before_phase4 + closingBudget.
//   By induction: |generated_after| <= |generatedPrefix| + steps_after. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Generate a complete SQL SELECT query answering the question. The query MUST have: SELECT <columns> FROM <table> [JOIN <table> ON ...] [WHERE ...] [GROUP BY ...] [HAVING ...] [ORDER BY ...] [LIMIT ...]. Use ONLY exact table and column names from the schema. Do not invent names. Place the complete SQL between << and >>.");

var steps: nat := 0;

// Phase 1: Short unconstrained preamble (at most 5 steps) for "SQL: " prefix
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force open constrained span if not already inside one
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Grounding-aware constrained SQL generation
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget: nat := 2;
  var sqlBudget: nat;
  if remaining > closeBudget {
    sqlBudget := remaining - closeBudget;
  } else {
    sqlBudget := 0;
  }
  if sqlBudget > 0 {
    var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
    var constrainedPrompt := prompt + stablePrefix;
    var resultConstrained := helpers.RegenerateUnitOnGroundingFailure(
      lm, parser, constrainedPrompt, currentConstrainedOut, eosToken, sqlBudget, 3, 20
    );
    generated := stablePrefix + resultConstrained;
    currentConstrainedOut := resultConstrained;
    steps := steps + sqlBudget;
  }
}

// Phase 4: Close constrained span using CloseSpanWithinBudget
if insideConstrainedOut && steps < maxSteps {
  var closingBudget := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closingBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closingBudget;
}

cost := steps;

